using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;
public static partial class CommunicationEndpoints {
 static void MapCampaigns(RouteGroupBuilder t){
 t.MapPost("/automations/member-greetings",async(Guid tenant,AppDb db,Access a)=>{
 foreach(var permission in new[]{"communications.templates","communications.automations","communications.send","communications.approve","members.read"})await a.Require(tenant,permission);
 await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);
 await MemberGreetings.Enable(db,tenant,a.UserId);a.Audit(tenant,"communication.member-greetings.enabled",tenant);
 await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{enabled=true,channel="InApp"});
 });
 t.MapGet("/received/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService cs)=>{await a.Member(tenant);var mine=cs.Mine(tenant).Select(m=>m.Id);var c=await db.Set<CommunicationCampaign>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id&&new[]{"Scheduled","Dispatching","Enqueued"}.Contains(c.Status)&&c.ScheduledAt<=DateTimeOffset.UtcNow&&(c.ExpiresAt==null||c.ExpiresAt>DateTimeOffset.UtcNow)&&db.Set<CampaignRecipient>().Any(r=>r.CampaignId==c.Id&&r.SnapshotVersion==c.SnapshotVersion&&r.UserId==a.UserId&&mine.Contains(r.MembershipId)))??throw new AccessDeniedException();var r=await db.Set<CampaignRecipient>().FirstAsync(r=>r.CampaignId==id&&r.SnapshotVersion==c.SnapshotVersion&&r.UserId==a.UserId);var vars=JsonSerializer.Deserialize<Dictionary<string,string>>(r.Variables)!;await db.Outbox.Where(o=>o.TenantId==tenant&&o.CampaignId==id&&o.UserId==a.UserId&&o.Channel=="InApp"&&o.DeliveredAt!=null).ExecuteUpdateAsync(x=>x.SetProperty(o=>o.ReadAt,DateTimeOffset.UtcNow));return Results.Ok(new{c.Id,c.Name,subject=CommunicationService.Render(c.Subject,vars),body=CommunicationService.Render(c.Body,vars),c.Priority,c.Acknowledge,acknowledged=r.AcknowledgedAt!=null});});

 t.MapPost("/audiences/preview",async(Guid tenant,Guid? unit,string channel,AudienceRules r,Access a,CommunicationService s)=>{var q=await s.Audience(tenant,unit,r);var rows=await s.Resolve(tenant,q,channel);return Results.Ok(new{affiliations=await q.CountAsync(),uniquePeople=rows.Count,eligible=rows.Count(r=>r.Reason=="Eligible"),duplicates=rows.Sum(r=>r.Duplicates),excluded=rows.Count(r=>r.Reason!="Eligible"),missingContact=rows.Count(r=>r.Reason=="Missing contact"),optedOut=rows.Count(r=>r.Reason=="Opted out"),suppressed=rows.Count(r=>r.Reason=="Suppressed"),members=rows.Take(100).Select(r=>new{r.MembershipId,r.Name,r.ChapterId,r.Reason})});});
 t.MapGet("/audiences",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);return await db.Set<CommunicationAudience>().Where(v=>v.TenantId==tenant&&v.OwnerId==a.UserId).OrderBy(v=>v.Name).Take(100).ToListAsync();});
 t.MapPost("/audiences",async(Guid tenant,AudienceSave r,AppDb db,Access a,CommunicationService s)=>{await s.Audience(tenant,r.UnitId,r.Rules);if(string.IsNullOrWhiteSpace(r.Name)||r.Name.Length>100)throw new DomainException("Name this audience");var audience=new CommunicationAudience{TenantId=tenant,UnitId=r.UnitId,OwnerId=a.UserId,Name=r.Name,Rules=JsonSerializer.Serialize(r.Rules)};db.Add(audience);a.Audit(tenant,"communication.audience.saved",audience.Id);await db.SaveChangesAsync();return Results.Ok(audience);});
 t.MapGet("/templates",async(Guid tenant,Guid? workspace,AppDb db,Access a)=>{await a.Member(tenant);var units=a.Visible(tenant,"communications.send").Select(u=>u.Id);var query=db.Set<CommunicationTemplate>().Where(t=>t.TenantId==tenant&&(t.UnitId==null&&units.Any()||t.UnitId!=null&&units.Contains(t.UnitId.Value)));return await query.OrderBy(t=>t.Name).Take(200).Select(t=>new{t.Id,t.UnitId,t.Name,t.Channel,t.Category,t.Language,t.Subject,t.Body,t.ProviderName,t.ProviderStatus,t.ProviderAccountId,t.Active,t.Revision}).ToListAsync();});
 t.MapPost("/templates",async(Guid tenant,TemplateWrite r,AppDb db,Access a,CommunityService history)=>{await a.Require(tenant,"communications.templates",r.UnitId);Validate(r);var template=new CommunicationTemplate{TenantId=tenant};ApplyTemplate(template,r);db.Add(template);history.Version(tenant,template.Id,"CommunicationTemplate",0,template);await db.SaveChangesAsync();return Results.Ok(template);});
 t.MapPut("/templates/{id:guid}",async(Guid tenant,Guid id,TemplateWrite r,AppDb db,Access a,CommunityService history)=>{var template=await db.Set<CommunicationTemplate>().SingleOrDefaultAsync(t=>t.TenantId==tenant&&t.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.templates",template.UnitId);if(template.UnitId!=r.UnitId)throw new DomainException("Template organization is immutable");if(template.Revision!=r.Revision)return Results.Conflict();Validate(r);ApplyTemplate(template,r);template.Revision++;history.Version(tenant,id,"CommunicationTemplate",template.Revision,template);await db.SaveChangesAsync();return Results.Ok(template);});
 t.MapPost("/templates/{id:guid}/preview",async(Guid tenant,Guid id,Guid membershipId,AppDb db,Access a,CommunicationService s,MembershipService ms)=>{var template=await db.Set<CommunicationTemplate>().SingleOrDefaultAsync(t=>t.TenantId==tenant&&t.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.send",template.UnitId);var allowed=(await ms.Directory(tenant)).Where(m=>m.Id==membershipId);var rows=await s.Resolve(tenant,allowed,template.Channel);var sample=rows.FirstOrDefault()??throw new AccessDeniedException();return Results.Ok(new{subject=CommunicationService.Render(template.Subject,sample.Variables),body=CommunicationService.Render(template.Body,sample.Variables)});});
 t.MapGet("/campaigns",async(Guid tenant,Guid? workspace,string? kind,string? status,AppDb db,Access a)=>{await a.Member(tenant);var units=a.InWorkspace(a.Visible(tenant,"communications.send"),tenant,workspace).Select(u=>u.Id);var all=workspace==null&&await a.Can(tenant,"communications.send");var reviewUnits=a.Visible(tenant,"communications.approve").Select(u=>u.Id);var reviewAll=await a.Can(tenant,"communications.approve");var q=db.Set<CommunicationCampaign>().Where(c=>c.TenantId==tenant&&(all||c.AuthorId==a.UserId||c.UnitId!=null&&units.Contains(c.UnitId.Value)||c.Status=="Pending Approval"&&(reviewAll||c.UnitId!=null&&reviewUnits.Contains(c.UnitId.Value))));if(kind!=null)q=q.Where(c=>c.Kind==kind);if(status!=null)q=q.Where(c=>c.Status==status);return await q.OrderByDescending(c=>c.CreatedAt).Take(100).Select(c=>new{c.Id,c.Name,c.Kind,c.Channel,c.Status,c.UnitId,c.ScheduledAt,c.ExpiresAt,c.SnapshotCount,c.EnqueuedCount,c.Revision,c.CreatedAt}).ToListAsync();});
 t.MapPost("/campaigns",async(Guid tenant,CampaignWrite r,AppDb db,Access a,CommunicationService s,CommunityService history)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var c=new CommunicationCampaign{TenantId=tenant,AuthorId=a.UserId};await ApplyCampaign(c,r,db,a,s);db.Add(c);if(r.Submit)await s.Snapshot(c);history.Version(tenant,c.Id,c.Kind,0,c);a.Audit(tenant,"communication.campaign.created",c.Id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(c);});
 t.MapGet("/campaigns/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a)=>{var c=await db.Set<CommunicationCampaign>().AsNoTracking().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();if(!await a.Can(tenant,"communications.send",c.UnitId)&&!await a.Can(tenant,"communications.approve",c.UnitId))throw new AccessDeniedException();return Results.Ok(new{campaign=c,recipients=await db.Set<CampaignRecipient>().Where(r=>r.CampaignId==id&&r.SnapshotVersion==c.SnapshotVersion).OrderBy(r=>r.Id).Take(100).Select(r=>new{r.Id,r.MembershipId,r.Status,r.AcknowledgedAt,r.OutboxId}).ToListAsync(),decisions=await db.Set<CommunityDecision>().Where(d=>d.TenantId==tenant&&d.ResourceId==id).OrderBy(d=>d.At).ToListAsync(),canReview=c.AuthorId!=a.UserId&&await a.Can(tenant,"communications.approve",c.UnitId)});});
 t.MapPut("/campaigns/{id:guid}",async(Guid tenant,Guid id,CampaignWrite r,AppDb db,Access a,CommunicationService s,CommunityService history)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var c=await db.Set<CommunicationCampaign>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.send",c.UnitId);if(c.Revision!=r.Revision)return Results.Conflict();if(c.EnqueuedCount>0||c.Status is "Cancelled" or "Dispatching" or "Enqueued")throw new DomainException("Duplicate this campaign to change already dispatched content");c.SnapshotVersion++;c.SnapshotAt=null;c.SnapshotCount=0;await ApplyCampaign(c,r,db,a,s);if(r.Submit)await s.Snapshot(c);c.Revision++;history.Version(tenant,id,c.Kind,c.Revision,c);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(c);});
 t.MapPost("/campaigns/{id:guid}/decision",async(Guid tenant,Guid id,CommunityReview r,AppDb db,Access a,CommunityService review,CommunicationService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var c=await db.Set<CommunicationCampaign>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();if(c.Revision!=r.Revision)return Results.Conflict();if(c.Status!="Pending Approval")throw new DomainException("Campaign is not awaiting review");if(c.SnapshotCount>(await s.Policy(tenant)).HighVolumeThreshold)await a.Require(tenant,"communications.highvolume",c.UnitId);await review.Decision(tenant,id,c.AuthorId,c.UnitId,c.Kind,c.Stages,c.Stage,r);if(r.Decision=="Approve"){c.Stage++;if(c.Stage==CommunityService.Stages(c.Stages).Length)c.Status="Scheduled";}else c.Status=r.Decision=="Reject"?"Rejected":"Changes Requested";c.Revision++;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(c);});
 t.MapPost("/campaigns/{id:guid}/cancel",async(Guid tenant,Guid id,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var c=await db.Set<CommunicationCampaign>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.send",c.UnitId);c.Status="Cancelled";c.Revision++;await db.Outbox.Where(o=>o.CampaignId==id&&(o.Status=="Queued"||o.Status=="Retry")).ExecuteUpdateAsync(x=>x.SetProperty(o=>o.Status,"Cancelled"));a.Audit(tenant,"communication.campaign.cancelled",id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
 t.MapPost("/campaigns/{id:guid}/duplicate",async(Guid tenant,Guid id,AppDb db,Access a)=>{var c=await db.Set<CommunicationCampaign>().AsNoTracking().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.send",c.UnitId);c.Id=Guid.NewGuid();c.AuthorId=a.UserId;c.Name="Copy of "+c.Name;c.Status="Draft";c.Stage=0;c.Revision=0;c.SnapshotCount=0;c.EnqueuedCount=0;c.SnapshotVersion=0;c.SnapshotAt=null;c.CreatedAt=DateTimeOffset.UtcNow;db.Add(c);a.Audit(tenant,"communication.campaign.duplicated",c.Id);await db.SaveChangesAsync();return Results.Ok(c);});
 t.MapGet("/announcements",async(Guid tenant,AppDb db,Access a,CommunityService cs)=>{await a.Member(tenant);var mine=cs.Mine(tenant).Select(m=>m.Id);return await db.Set<CommunicationCampaign>().Where(c=>c.TenantId==tenant&&c.Kind=="Announcement"&&new[]{"Scheduled","Dispatching","Enqueued"}.Contains(c.Status)&&c.ScheduledAt<=DateTimeOffset.UtcNow&&(c.ExpiresAt==null||c.ExpiresAt>DateTimeOffset.UtcNow)&&db.Set<CampaignRecipient>().Any(r=>r.CampaignId==c.Id&&r.SnapshotVersion==c.SnapshotVersion&&r.UserId==a.UserId&&mine.Contains(r.MembershipId))).OrderByDescending(c=>c.Pinned).ThenByDescending(c=>c.ScheduledAt).Take(100).Select(c=>new{c.Id,c.Name,c.Subject,c.Body,c.UnitId,c.Priority,c.Pinned,c.Acknowledge,c.ScheduledAt,c.ExpiresAt,acknowledged=db.Set<CampaignRecipient>().Any(r=>r.CampaignId==c.Id&&r.UserId==a.UserId&&r.AcknowledgedAt!=null)}).ToListAsync();});
 t.MapPost("/announcements/{id:guid}/acknowledge",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService cs)=>{await a.Member(tenant);var mine=cs.Mine(tenant).Select(m=>m.Id);var c=await db.Set<CommunicationCampaign>().SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==id&&c.Kind=="Announcement"&&c.ScheduledAt<=DateTimeOffset.UtcNow&&c.Status!="Cancelled")??throw new AccessDeniedException();var r=await db.Set<CampaignRecipient>().SingleOrDefaultAsync(r=>r.CampaignId==id&&r.SnapshotVersion==c.SnapshotVersion&&r.UserId==a.UserId&&mine.Contains(r.MembershipId))??throw new AccessDeniedException();r.AcknowledgedAt=DateTimeOffset.UtcNow;a.Audit(tenant,"communication.announcement.acknowledged",id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapGet("/automations",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);var units=a.Visible(tenant,"communications.automations").Select(u=>u.Id);var all=await a.Can(tenant,"communications.automations");return await db.Set<CommunicationAutomation>().Where(r=>r.TenantId==tenant&&(all||r.UnitId!=null&&units.Contains(r.UnitId.Value))).OrderBy(r=>r.Name).Take(100).ToListAsync();});
 t.MapPost("/automations",async(Guid tenant,AutomationWrite r,AppDb db,Access a,CommunicationService s)=>{await a.Require(tenant,"communications.automations",r.UnitId);await s.Audience(tenant,r.UnitId,r.Audience);if(!CommunicationService.Triggers.Contains(r.Trigger)||r.OffsetMinutes is <-525600 or >525600||r.RepeatMinutes is <0 or >525600||r.Trigger=="Recurring"&&r.RepeatMinutes<60||string.IsNullOrWhiteSpace(r.Name)||r.Name.Length>100)throw new DomainException("Invalid automation trigger or interval");if(r.Trigger is "MemberBirthday" or "WeddingAnniversary" or "MembershipAnniversary")await a.Require(tenant,"members.read",r.UnitId);if(!await db.Set<CommunicationTemplate>().AnyAsync(t=>t.TenantId==tenant&&t.Id==r.TemplateId&&t.Channel==r.Channel&&t.Active))throw new DomainException("Choose an active channel template");if(r.AccountId!=null&&!await db.Set<CommunicationAccount>().AnyAsync(ac=>ac.TenantId==tenant&&ac.Id==r.AccountId))throw new AccessDeniedException();var rule=new CommunicationAutomation{TenantId=tenant,AuthorId=a.UserId,UnitId=r.UnitId,TemplateId=r.TemplateId,AccountId=r.AccountId,Name=r.Name,Trigger=r.Trigger,Channel=r.Channel,Audience=JsonSerializer.Serialize(r.Audience),OffsetMinutes=r.OffsetMinutes,RepeatMinutes=r.RepeatMinutes,Enabled=r.Enabled,TestMode=r.TestMode};db.Add(rule);a.Audit(tenant,"communication.automation.created",rule.Id);await db.SaveChangesAsync();return Results.Ok(rule);});
 t.MapPost("/automations/{id:guid}/toggle",async(Guid tenant,Guid id,AppDb db,Access a)=>{var rule=await db.Set<CommunicationAutomation>().SingleOrDefaultAsync(r=>r.TenantId==tenant&&r.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.automations",rule.UnitId);rule.Enabled=!rule.Enabled;a.Audit(tenant,"communication.automation.toggled",id,new{rule.Enabled});await db.SaveChangesAsync();return Results.NoContent();});
 t.MapGet("/automations/{id:guid}/executions",async(Guid tenant,Guid id,AppDb db,Access a)=>{var rule=await db.Set<CommunicationAutomation>().SingleOrDefaultAsync(r=>r.TenantId==tenant&&r.Id==id)??throw new AccessDeniedException();await a.Require(tenant,"communications.automations",rule.UnitId);return await db.Set<AutomationExecution>().Where(e=>e.RuleId==id).OrderByDescending(e=>e.At).Take(100).ToListAsync();});
 }
 static void Validate(TemplateWrite r){if(!CommunicationService.Channels.Contains(r.Channel)||r.Subject.Length>180||r.Language.Length>20||r.Category.Length>100)throw new DomainException("Invalid template properties");CommunicationService.ValidateTemplate(r.Body);CommunicationService.ValidateTemplate(r.Subject);}
 static void ApplyTemplate(CommunicationTemplate t,TemplateWrite r){t.UnitId=r.UnitId;t.Name=r.Name;t.Channel=r.Channel;t.Body=r.Body;t.Subject=r.Subject;t.Category=r.Category;t.Language=r.Language;if(r.ProviderName!=t.ProviderName){t.ProviderStatus="Not submitted";t.ProviderAccountId=null;}t.ProviderName=r.ProviderName;t.Active=r.Active;}
 static async Task ApplyCampaign(CommunicationCampaign c,CampaignWrite r,AppDb db,Access a,CommunicationService s){await a.Require(c.TenantId,"communications.send",r.UnitId);await s.Audience(c.TenantId,r.UnitId,r.Audience);if(!CommunicationService.Channels.Contains(r.Channel)||r.Kind is not("Campaign" or "Announcement")||r.Priority is not("Normal" or "Important" or "Urgent")||r.ExpiresAt<r.ScheduledAt)throw new DomainException("Invalid campaign properties");if(r.TemplateId!=null){var template=await db.Set<CommunicationTemplate>().AsNoTracking().SingleOrDefaultAsync(t=>t.TenantId==c.TenantId&&t.Id==r.TemplateId&&t.Active&&t.Channel==r.Channel)??throw new AccessDeniedException();if(template.UnitId!=null)await a.Require(c.TenantId,"communications.send",template.UnitId);c.Body=template.Body;c.Subject=template.Subject;}else{CommunicationService.ValidateTemplate(r.Body);CommunicationService.ValidateTemplate(r.Subject);c.Body=r.Body;c.Subject=r.Subject;}if(string.IsNullOrWhiteSpace(c.Body)||c.Body.Length>12000||c.Subject.Length>180)throw new DomainException("Enter a bounded message body and subject");if(r.Channel!="InApp"){var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(ac=>ac.Id==r.AccountId&&ac.TenantId==c.TenantId&&ac.Channel==r.Channel)??throw new DomainException("Choose a channel sending account");if(account.UnitId!=null&&account.UnitId!=r.UnitId)throw new AccessDeniedException();}if(r.EventId!=null){var e=await db.Set<CommunityEvent>().SingleOrDefaultAsync(e=>e.Id==r.EventId&&e.TenantId==c.TenantId)??throw new AccessDeniedException();await a.Require(c.TenantId,"communications.send",e.UnitId);}c.UnitId=r.UnitId;c.Name=r.Name;c.Channel=r.Channel;c.Kind=r.Kind;c.AccountId=r.AccountId;c.TemplateId=r.TemplateId;c.EventId=r.EventId;c.Audience=JsonSerializer.Serialize(r.Audience);c.Priority=r.Priority;c.Pinned=r.Pinned;c.Acknowledge=r.Acknowledge;c.ScheduledAt=r.ScheduledAt?.ToUniversalTime()??DateTimeOffset.UtcNow;c.ExpiresAt=r.ExpiresAt?.ToUniversalTime();c.Stages=(await s.Policy(c.TenantId)).ApprovalStages;c.Stage=0;c.Status=r.Submit?(CommunityService.Stages(c.Stages).Length==0?"Scheduled":"Pending Approval"):"Draft";}
}
public record AudienceSave(string Name,Guid? UnitId,AudienceRules Rules);
